using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioDefaultShaderValidation {
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static StudioModelEditor editor;static StudioModelDocument doc;static MashBoxStudioViewport view;static AnimationStudioWindow host;static Material original;static int checks;static double ready;
 static string PathFor(string name)=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../"+name));static void Check(bool ok,string message){if(!ok)throw new Exception(message);checks++;}
 public static void Run(){EditorApplication.delayCall+=Start;}
 static void Start(){try{var globalType=Type.GetType("UnityEngine.Rendering.HighDefinition.HDRenderPipelineGlobalSettings, Unity.RenderPipelines.HighDefinition.Runtime");globalType.GetMethod("Ensure",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{true});var pipeline=(RenderPipelineAsset)ScriptableObject.CreateInstance(Type.GetType("UnityEngine.Rendering.HighDefinition.HDRenderPipelineAsset, Unity.RenderPipelines.HighDefinition.Runtime"));AssetDatabase.CreateAsset(pipeline,AssetDatabase.GenerateUniqueAssetPath("Assets/StudioShaderValidationPipeline.asset"));GraphicsSettings.defaultRenderPipeline=pipeline;QualitySettings.renderPipeline=pipeline;Check(GraphicsSettings.currentRenderPipeline&&GraphicsSettings.currentRenderPipeline.GetType().Name.Contains("HDRenderPipeline"),"HDRP pipeline active");var shader=AssetDatabase.LoadAssetAtPath<Shader>(AssetDatabase.GUIDToAssetPath("409bba92b9fbb904cbfd7cf58b9531a6"));Check(shader&&!ShaderUtil.ShaderHasError(shader),"Graph imports and compiles");defaultAsset=StudioMeshMaterialPreview.DefaultMaterial;originalColor=defaultAsset.GetColor("_BaseColor");defaultAsset.SetColor("_BaseColor",new Color(.8f,.1f,.1f));CheckCreatedMaterials();doc=ScriptableObject.CreateInstance<StudioModelDocument>();var mesh=StudioModelDocument.BuildPrimitive(PrimitiveType.Cube,out var polygons);original=new Material(GraphicsSettings.currentRenderPipeline.defaultMaterial);doc.nodes.Add(new StudioModelDocument.Node{name="Studio default",mesh=mesh,materials=new[]{defaultAsset},cutPolygons=polygons,cutTriangles=mesh.triangles});doc.lighting.studioLights=true;doc.lighting.ground=false;doc.lighting.exposure=0;AnimationStudioWindow.Open();host=Resources.FindObjectsOfTypeAll<AnimationStudioWindow>().First();typeof(AnimationStudioWindow).GetMethod("SwitchStudioMode",F).Invoke(host,new object[]{true});typeof(AnimationStudioWindow).GetMethod("LoadStudioModel",F).Invoke(host,new object[]{doc});editor=host.ToolbarModelEditor;editor.SetDisplayMode(true,false);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().First(v=>v.Studio==host);view.position=new Rect(60,60,800,650);view.LookAtDirect(Vector3.zero,Quaternion.Euler(20,35,0),2);ready=EditorApplication.timeSinceStartup+3;EditorApplication.update+=Tick;}catch(Exception e){Finish(e.ToString());}}
 static void CheckCreatedMaterials(){AssetDatabase.ImportAsset(AssetDatabase.GUIDToAssetPath("ef2f63690a486964faa40c2e3d756d1c"),ImportAssetOptions.ForceUpdate);var template=StudioMeshMaterialPreview.DefaultMaterial;Check(template&&AssetDatabase.GetAssetPath(template).EndsWith("MashBoxStudio_Default.mat"),"Shared default resolves packaged Studio asset");var created=ScriptableObject.CreateInstance<StudioModelDocument>();Directory.CreateDirectory(StudioModelDocument.WorkspaceFolder);created.SetWorkspacePath(Path.Combine(StudioModelDocument.WorkspaceFolder,"created-default-validation-"+Guid.NewGuid().ToString("N")+".workspace"));try{foreach(var kind in new[]{PrimitiveType.Cube,PrimitiveType.Plane,PrimitiveType.Quad,PrimitiveType.Sphere,PrimitiveType.Cylinder}){int index=created.AddPrimitive(kind);Check(created.nodes[index].materials.Length==1&&created.nodes[index].materials[0]==template,"Created "+kind+" uses Studio asset");}int first=created.nodes.Count;created.AddVehiclePart(new StudioVehiclePartCatalog.Template{vehicle="Bike",part="Frame",color="Default"});var vehicles=created.nodes.Skip(first).Where(n=>n.mesh).ToArray();Check(vehicles.Length>0,"Vehicle test created no geometry");var vehicleShader=AssetDatabase.LoadAssetAtPath<Shader>(AssetDatabase.GUIDToAssetPath("ef2f63690a486964faa40c2e3d756d1c"));Check(vehicleShader&&vehicles.All(n=>n.materials[0]&&n.materials[0].shader==vehicleShader),"Vehicle geometry uses vehicle shader");using(var defaults=new MaterialScope(vehicleShader)){foreach(var node in vehicles){for(int property=0;property<vehicleShader.GetPropertyCount();property++){string key=vehicleShader.GetPropertyName(property);switch(vehicleShader.GetPropertyType(property)){case ShaderPropertyType.Color:Check(node.materials[0].GetColor(key)==defaults.Value.GetColor(key),"Vehicle color default "+key);break;case ShaderPropertyType.Vector:Check(node.materials[0].GetVector(key)==defaults.Value.GetVector(key),"Vehicle vector default "+key);break;case ShaderPropertyType.Float:case ShaderPropertyType.Range:Check(node.materials[0].GetFloat(key)==defaults.Value.GetFloat(key),"Vehicle float default "+key);break;case ShaderPropertyType.Texture:Check(node.materials[0].GetTexture(key)==defaults.Value.GetTexture(key),"Vehicle texture default "+key);break;}}}}StudioWorkspaceText.Write(created,created.WorkspacePath);var loaded=StudioWorkspaceText.Read(created.WorkspacePath);try{Check(loaded.nodes.Take(first).All(n=>n.materials[0]==template),"Studio asset material survives workspace round trip");Check(loaded.nodes.Skip(first).Where(n=>n.mesh).All(n=>n.materials[0]&&n.materials[0].shader==vehicleShader),"Vehicle shader survives workspace round trip");}finally{foreach(var node in loaded.nodes)if(node.mesh)Object.DestroyImmediate(node.mesh);Object.DestroyImmediate(loaded);}
}finally{foreach(var node in created.nodes)if(node.mesh)Object.DestroyImmediate(node.mesh);Object.DestroyImmediate(created);}}
 static int blackPhase;static string diagnostics="";static Material defaultAsset;static Color originalColor;
 static Color32[] Native(string file){var field=typeof(MashBoxStudioViewport).GetField("cachedScene",F);var rt=field.GetValue(view) as RenderTexture;if(!rt||!rt.IsCreated())return null;var previous=RenderTexture.active;try{RenderTexture.active=rt;var image=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();File.WriteAllBytes(PathFor(file),image.EncodeToPNG());var pixels=image.GetPixels32();Object.DestroyImmediate(image);return pixels;}finally{RenderTexture.active=previous;}}
 static void Tick(){if(EditorApplication.timeSinceStartup<ready)return;try{var pixels=Native("neutral-toggle-"+blackPhase+".png");if(pixels==null){view.Repaint();ready=EditorApplication.timeSinceStartup+.5;return;}var renderer=editor.Transforms[0].GetComponent<Renderer>();var material=renderer.sharedMaterial;int red=pixels.Count(c=>c.r>30&&c.r>c.g*1.5f&&c.r>c.b*1.5f),green=pixels.Count(c=>c.g>60&&c.g>c.r*1.5f&&c.g>c.b*1.5f),gray=pixels.Count(c=>c.r>85&&Math.Abs(c.r-c.g)<3&&Math.Abs(c.r-c.b)<3);diagnostics+="phase="+blackPhase+" studio="+doc.lighting.studioLights+" red="+red+" green="+green+" gray="+gray+"\n";
 if(blackPhase==0){editor.EditLighting(s=>s.studioLights=false);editor.SetDisplayMode(true,true);blackPhase=1;}
 else if(blackPhase==1){Check(red>100,"Assigned red absent in camera material view");editor.SetDisplayMode(true,false);blackPhase=2;}
 else if(blackPhase==2){Check(gray>100&&red<20,"Neutral camera view inherits assigned color");Check(material.shader.name=="MashBox/Studio/Preview"&&material.GetFloat("_CameraLighting")==1,"Neutral view does not compute camera lighting");Check(material.GetColor("_Color")==new Color(.65f,.65f,.65f),"Neutral tint is not fixed");editor.SetDisplayMode(true,true);blackPhase=3;}
 else if(blackPhase==3){Check(red>100,"Material toggle failed to restore assigned red");editor.EditLighting(s=>s.studioLights=true);editor.SetDisplayMode(true,false);blackPhase=4;}
 else if(blackPhase==4){Check(gray>100&&red<20&&material.shader.name=="MashBox/Studio/Preview","Studio Lights neutral view is not computed neutral");editor.SetDisplayMode(true,true);blackPhase=5;}
 else if(blackPhase==5){Check(red>100,"Studio Lights material view lost assigned shader/color");editor.EditLighting(s=>s.studioLights=false);editor.SetDisplayMode(true,true);UnityEditor.Undo.RecordObject(defaultAsset,"Test live assigned tint");defaultAsset.SetColor("_BaseColor",new Color(.05f,.6f,.05f));EditorUtility.SetDirty(defaultAsset);UnityEditor.Undo.FlushUndoRecordObjects();blackPhase=6;}
 else if(blackPhase==6){Check(green>100,"Assigned material color does not refresh live");editor.SetDisplayMode(true,false);blackPhase=7;}
 else if(blackPhase==7){Check(gray>100&&green<20,"Neutral shading changed with assigned green");Check(doc.nodes[0].materials[0]==defaultAsset,"Preview toggle modified source assignment");EditorApplication.update-=Tick;Finish("PASS "+checks+" native red/neutral/red, both lighting modes and live assigned-color checks\n"+diagnostics);return;}
 ready=EditorApplication.timeSinceStartup+1;view.MarkDirty(MashBoxStudioViewport.DirtyState.Scene);
 }catch(Exception e){EditorApplication.update-=Tick;Finish(diagnostics+e);}}
 sealed class MaterialScope:IDisposable{internal Material Value;internal MaterialScope(Shader s){Value=new Material(s);}public void Dispose(){Object.DestroyImmediate(Value);}}
 static void Finish(string result){EditorApplication.update-=Tick;if(defaultAsset)defaultAsset.SetColor("_BaseColor",originalColor);File.WriteAllText(PathFor("studio-default-shader-result.txt"),result);EditorApplication.delayCall+=()=>{if(view)view.Close();if(host)Object.DestroyImmediate(host);double end=EditorApplication.timeSinceStartup+1;void Exit(){if(EditorApplication.timeSinceStartup<end)return;EditorApplication.update-=Exit;EditorApplication.Exit(result.StartsWith("PASS")?0:1);}EditorApplication.update+=Exit;};}
}
